constexpr int TILE_OW = 8;
constexpr int TILE_CO = 8;
constexpr int BLOCK_THREADS = 256;

__global__ void conv2d_tiled_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    float* __restrict__ y,
    int N, int C, int H, int W,
    int M, int KH, int KW,
    int strideH, int strideW,
    int padH, int padW,
    int OH, int OW,
    int inTileH, int inTileW)
{
    const int tid = threadIdx.x;
    const int n = blockIdx.z;
    const int oh0 = blockIdx.y * TILE_OH;
    const int ow0 = blockIdx.x * TILE_OW;

    extern __shared__ float smem[];
    const int inElems = C * inTileH * inTileW;
    const int wElemsPerCo = C * KH * KW;
    float* sh_in = smem;
    float* sh_w = smem + inElems;

    const int inBaseH = oh0 * strideH - padH;
    const int inBaseW = ow0 * strideW - padW;

    for (int idx = tid; idx < inElems; idx += blockDim.x) {
        const int ci = idx / (inTileH * inTileW);
        const int rem = idx - ci * (inTileH * inTileW);
        const int ih = rem / inTileW;
        const int iw = rem - ih * inTileW;
        const int gh = inBaseH + ih;
        const int gw = inBaseW + iw;

        float v = 0.0f;
        if (gh >= 0 && gh < H && gw >= 0 && gw < W) {
            v = x[((n * C + ci) * H + gh) * W + gw];
        }
        sh_in[idx] = v;
    }
    __syncthreads();

    const int spatial = TILE_OH * TILE_OW;
    const int total = spatial * TILE_CO;
    const int wChunkElems = TILE_CO * wElemsPerCo;

    for (int co0 = 0; co0 < M; co0 += TILE_CO) {
        for (int idx = tid; idx < wChunkElems; idx += blockDim.x) {
            const int coL = idx / wElemsPerCo;
            const int rem = idx - coL * wElemsPerCo;
            const int ci = rem / (KH * KW);
            const int krem = rem - ci * (KH * KW);
            const int kh = krem / KW;
            const int kw = krem - kh * KW;
            const int co = co0 + coL;

            float v = 0.0f;
            if (co < M) {
                v = w[((co * C + ci) * KH + kh) * KW + kw];
            }
            sh_w[idx] = v;
        }
        __syncthreads();

        for (int idx = tid; idx < total; idx += blockDim.x) {
            const int coL = idx / spatial;
            const int sp = idx - coL * spatial;
            const int ohL = sp / TILE_OW;
            const int owL = sp - ohL * TILE_OW;

            const int co = co0 + coL;
            const int oh = oh0 + ohL;
            const int ow = ow0 + owL;

            if (co < M && oh < OH && ow < OW) {
                float acc = b[co];
                #pragma unroll
                for (int ci = 0; ci < C; ++ci) {
                    #pragma unroll
                    for (int kh = 0; kh < KH; ++kh) {
                        const int ih = ohL * strideH + kh;
                        #pragma unroll
                        for (int kw = 0; kw < KW; ++kw) {
                            const int iw = owL * strideW + kw;
                            acc += sh_in[(ci * inTileH + ih) * inTileW + iw] *
                                   sh_w[(coL * wElemsPerCo) + ((ci * KH + kh) * KW + kw)];
                        }
                    }
                }
                y[((n * M + co) * OH + oh) * OW + ow] = acc;
            }
        }
        __syncthreads();
    }
}

torch::Tensor conv2d_forward(torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
                             int64_t stride, int64_t padding)
{
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(bias.is_cuda(), "bias must be CUDA");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "only float32 is supported");
    TORCH_CHECK(weight.scalar_type() == torch::kFloat32, "only float32 is supported");
    TORCH_CHECK(bias.scalar_type() == torch::kFloat32, "only float32 is supported");

    auto x = input.contiguous();
    auto w = weight.contiguous();
    auto b = bias.contiguous();

    const int N = (int)x.size(0);
    const int C = (int)x.size(1);
    const int H = (int)x.size(2);
    const int W = (int)x.size(3);

    const int M = (int)w.size(0);
    const int KH = (int)w.size(2);
    const int KW = (int)w.size(3);
    TORCH_CHECK((int)w.size(1) == C, "channel mismatch");

    const int strideH = (int)stride;
    const int strideW = (int)stride;
    const int padH = (int)padding;
    const int padW = (int)padding;

    const int OH = (H + 2 * padH - KH) / strideH + 1;
    const int OW = (W + 2 * padW - KW) / strideW + 1;
    TORCH_CHECK(OH > 0 && OW > 0, "invalid output shape");

    auto y = torch::empty({N, M, OH, OW}, x.options());

    const int inTileH = (TILE_OH - 1) * strideH + KH;
    const int inTileW = (TILE_OW - 1) * strideW + KW;
    const size_t smem_elems =
        (size_t)C * inTileH * inTileW + (size_t)TILE_CO * C * KH * KW;
    const size_t smem_bytes = smem_elems * sizeof(float);
    int dev = 0;
    C10_CUDA_CHECK(cudaGetDevice(&dev));
    int maxOptin = 0;
    C10_CUDA_CHECK(cudaDeviceGetAttribute(&maxOptin,
                    cudaDevAttrMaxSharedMemoryPerBlockOptin, dev));
    TORCH_CHECK(smem_bytes <= (size_t)maxOptin,
                "shared memory requirement too large: ", smem_bytes, " > ", maxOptin);
    if (smem_bytes > 48 * 1024) {
        static bool configured = false;
        if (!configured) {
            C10_CUDA_CHECK(cudaFuncSetAttribute(conv2d_tiled_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             (int)smem_bytes));
            configured = true;
        }
    }

    dim3 block(BLOCK_THREADS);
    dim3 grid((OW + TILE_OW - 1) / TILE_OW,
              (OH + TILE_OH - 1) / TILE_OH,
              N);

    auto stream = at::cuda::getCurrentCUDAStream();
    conv2d_tiled_kernel<<<grid, block, smem_bytes, stream>>>(
        x.data_ptr<float>(), w.data_ptr<float>(), b.data_ptr<float>(), y.data_ptr<float>(),
        N, C, H, W, M, KH, KW, strideH, strideW, padH, padW, OH, OW, inTileH, inTileW);
    C10_CUDA_KERNEL_LAUNCH_CHECK();

    return y;
}
